// Extrai o lead da mensagem recebida pela WAHA.
//
// IMPORTANTE: o caminho do ctwa_clid muda conforme o engine (NOWEB,
// WEBJS, GOWS) e a versao da WAHA. Por isso a busca abaixo e defensiva:
// varre varios caminhos conhecidos e, se nao achar, faz uma varredura
// recursiva procurando qualquer chave que se pareca com ctwaClid.
//
// >>> Rode uma vez com um lead real e olhe 'debug_caminho_encontrado'
//     na saida para confirmar onde o campo veio. Depois pode simplificar.

const body = $json.body ?? {};
const payload = body.payload ?? {};

// --- ignora mensagens enviadas por nos e mensagens de grupo ---
if (payload.fromMe === true) {
  return [];
}
const from = String(payload.from ?? '');
if (from.endsWith('@g.us') || from === 'status@broadcast') {
  return [];
}

// --- telefone ---
const telefone = from.replace(/@.*$/, '').replace(/\D/g, '');
if (!telefone) {
  return [];
}

// --- nome do contato ---
const nome =
  payload._data?.notifyName ??
  payload.notifyName ??
  payload._data?.pushName ??
  payload.pushName ??
  null;

// --- busca do ctwa_clid em caminhos conhecidos ---
const ctx =
  payload._data?.contextInfo ??
  payload.contextInfo ??
  payload._data?.message?.extendedTextMessage?.contextInfo ??
  {};
const ext = ctx.externalAdReply ?? ctx.external_ad_reply ?? {};

const candidatos = [
  ['contextInfo.externalAdReply.ctwaClid', ext.ctwaClid],
  ['contextInfo.externalAdReply.ctwa_clid', ext.ctwa_clid],
  ['contextInfo.ctwaClid', ctx.ctwaClid],
  ['contextInfo.ctwa_clid', ctx.ctwa_clid],
  ['adReferral.ctwaClid', payload.adReferral?.ctwaClid],
  ['referral.ctwa_clid', payload.referral?.ctwa_clid]
];

let ctwaClid = null;
let caminho = null;
for (const [nomeCaminho, valor] of candidatos) {
  if (valor && String(valor).trim() !== '') {
    ctwaClid = String(valor).trim();
    caminho = nomeCaminho;
    break;
  }
}

// --- rede de seguranca: varredura recursiva ---
function varrer(obj, prefixo = '', profundidade = 0) {
  if (!obj || typeof obj !== 'object' || profundidade > 8) return null;
  for (const [k, v] of Object.entries(obj)) {
    const chave = k.toLowerCase().replace(/_/g, '');
    if (chave === 'ctwaclid' && v && String(v).trim() !== '') {
      return { valor: String(v).trim(), caminho: `${prefixo}${k}` };
    }
    if (v && typeof v === 'object') {
      const achado = varrer(v, `${prefixo}${k}.`, profundidade + 1);
      if (achado) return achado;
    }
  }
  return null;
}

if (!ctwaClid) {
  const achado = varrer(payload);
  if (achado) {
    ctwaClid = achado.valor;
    caminho = `varredura:${achado.caminho}`;
  }
}

// --- origem do anuncio ---
const adSourceId =
  ext.sourceId ?? ext.source_id ??
  payload.adReferral?.sourceId ??
  payload.referral?.source_id ?? null;

const adEntryPoint =
  ext.sourceType ?? ext.source_type ??
  payload.adReferral?.sourceType ?? null;

return [{
  json: {
    session_name: body.session ?? payload.session ?? null,
    telefone,
    nome,
    ctwa_clid: ctwaClid,
    ad_source_id: adSourceId ? String(adSourceId) : null,
    ad_entry_point: adEntryPoint ? String(adEntryPoint) : null,
    veio_de_anuncio: Boolean(ctwaClid || adSourceId),
    debug_caminho_encontrado: caminho,
    debug_payload_bruto: JSON.stringify(payload).slice(0, 4000)
  }
}];

const lead = $json;
const webhook = $('Webhook WAHA').item.json.body ?? {};
return [{ json: {
  session_name: lead.session_name,
  telefone: lead.telefone,
  nome: lead.nome,
  ctwa_clid: lead.ctwa_clid,
  ad_source_id: lead.ad_source_id,
  ad_entry_point: lead.ad_entry_point,
  veio_de_anuncio: lead.veio_de_anuncio,
  event_id: String(webhook.id ?? webhook.payload?.id ?? '').trim() || null
} }];

// Normaliza o evento session.status da WAHA.
const body = $json.body ?? {};
const payload = body.payload ?? {};

return [{
  json: {
    session_name: body.session ?? payload.name ?? null,
    status: String(payload.status ?? '').toUpperCase(),
    phone_number: payload.me?.id ? String(payload.me.id).replace(/@.*$/, '') : null,
    push_name: payload.me?.pushName ?? null,
    erro: payload.error ?? payload.message ?? null
  }
}];
